# Independent reviewer decoder for hcp-1033: key written out by hand (not generated by rule).
import re, sys, collections
K = dict(zip(range(1, 26), "VWXYZQRSTULMNOPFGHIKABCDE"))
txt = open(sys.argv[1], encoding="utf-8").read().splitlines()
words, nums = [], []
for ln in txt:
    if ln.startswith("#") or not ln.strip(): continue
    for w in re.split(r"\s+-\s+|\s-\s*$|\s+", ln):
        ns = re.findall(r"\{?(\d+)\}?(\"?)", w)
        if not ns: continue
        s = "".join(({"A":"Ä","O":"Ö","U":"Ü"}[K[int(n)]] if u else K[int(n)]) for n, u in ns)
        nums += [int(n) for n, _ in ns]
        words.append(s + ("=" if w.endswith(("=", ":")) else ""))
print(" ".join(words).replace("= ", ""))
c = collections.Counter(nums)
print("numbers:", len(nums), "distinct:", sorted(c), "unused:", [n for n in range(1, 26) if n not in c])
